package com.bank.featcode.service;

import com.bank.featcode.trie.TrieNode;
import java.util.List;
import java.util.logging.Logger;

// Longest word whose every prefix is also a word, via word-only descent.
public class FeatureCodeService {
    private static final Logger log = Logger.getLogger(FeatureCodeService.class.getName());
    private String best = "";

    public String longestBuildable(List<String> codes) {
        TrieNode root = new TrieNode();
        for (String code : codes) {                 // build the trie
            TrieNode node = root;
            for (char c : code.toCharArray())
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            node.isWord = true;
        }
        best = "";
        dfs(root, new StringBuilder());
        final String r = best;
        log.info(() -> "Longest buildable code = " + r);
        return best;
    }

    private void dfs(TrieNode node, StringBuilder path) {
        // sorted children give dictionary-order preference automatically
        for (var entry : node.children.entrySet()) {
            TrieNode child = entry.getValue();
            if (!child.isWord) continue;            // prefix not a word, cannot build here
            path.append(entry.getKey());
            if (path.length() > best.length())       // longer wins; sorted order breaks ties
                best = path.toString();
            dfs(child, path);
            path.deleteCharAt(path.length() - 1);   // backtrack
        }
    }
}
