package com.bank.featcode;

import com.bank.featcode.service.FeatureCodeService;
import java.util.List;
import java.util.logging.Logger;

public class FeatureCodeApplication {
    private static final Logger log = Logger.getLogger(FeatureCodeApplication.class.getName());

    public static void main(String[] args) {
        FeatureCodeService service = new FeatureCodeService();
        List<String> codes = List.of("A", "AP", "APP", "APPL", "APPLE", "B");
        String longest = service.longestBuildable(codes);
        log.info("Longest incrementally buildable feature code: " + longest);
    }
}
